	The question distribution is as follows: the verifier samples $\mathsf{Constraint}_i$ uniformly from $\mathcal T^{\mathrm{mc}}$, then samples $\mathsf{Variable}_j$ uniformly among the three variables appearing in the row or column of $\mathsf{Constraint}_i$; one player, chosen uniformly at random, receives $\mathsf{Constraint}_i$ and the other receives $\mathsf{Variable}_j$. Equivalently, the verifier samples a uniformly random edge of the bipartite \emph{type graph} $G^{\mathrm{ms}}$ on vertex sets $\mathcal T^{\mathrm{mc}}$ and $\mathcal T^{\mathrm{mv}}$, whose edges are $\mathsf{Constraint}_i \,\text{---}\, \mathsf{Variable}_{3(i-1)+j}$ for $i,j \in \{1,2,3\}$ and $\mathsf{Constraint}_i \,\text{---}\, \mathsf{Variable}_{(i-3)+3(j-1)}$ for $i \in \{4,5,6\}$, $j \in \{1,2,3\}$ ($18$ edges in total, and no self-loops), and sends one endpoint to a uniformly random player and the other endpoint to the other player.

	The $\mathsf{Constraint}$ player answers with three bits $(\beta_{v_1}, \beta_{v_2}, \beta_{v_3}) \in \F_2^3$, where $(v_1,v_2,v_3)$ are the indices of the three variables of $\mathsf{Constraint}_i$; the $\mathsf{Variable}$ player answers with a single bit $\gamma \in \F_2$. The players win if and only if the $\mathsf{Constraint}$ player's answer satisfies the equation associated with $\mathsf{Constraint}_i$ and $\gamma = \beta_j$.
\end{definition}

The following theorem records the self-testing (rigidity) properties of the Magic Square game. It is used in the soundness analysis of the Pauli basis test to enforce anticommutation relations between certain pairs of observables.
With zero-based labels, the paper's variables $1$ and $5$ have labels $0$ and
$4$, respectively.

\begin{theorem}[Rigidity of the Magic Square game]\label{thm:ms-rigidity}
		\lean{MIPStarRE.QPBT.exists_ms_rigidity}
		% tracked in issue #172
		\uses{def:ms-game, def:symmetric-game, def:tensor-product-value, def:EPR,
			def:povm-distance}
		View $\mathfrak{G}^{\mathrm{MS}}$ as a symmetric game, and let
		$\mathcal S = (\ket{\psi}, M)$ be a symmetric strategy that succeeds in
		it with probability at least $1-\eps$, where
		$\ket{\psi} \in \hilb_{\mathrm A} \ot \hilb_{\mathrm B}$.  Write
		$A=B=M$ for the two players' measurement families.  Then there exist local
		isometries $\phi_{\mathrm A}\colon \hilb_{\mathrm A} \to
		\hilb_{\mathrm A'} \ot \hilb_{\mathrm A''}$ and
		$\phi_{\mathrm B}\colon \hilb_{\mathrm B} \to
		\hilb_{\mathrm B'} \ot \hilb_{\mathrm B''}$, where
		$\hilb_{\mathrm A'}, \hilb_{\mathrm B'} \cong (\C^2)^{\ot 2}$ and
		$\hilb_{\mathrm A''}, \hilb_{\mathrm B''}$ are finite dimensional, and a
		state $\ket{\mathrm{aux}} \in \hilb_{\mathrm A''} \ot
		\hilb_{\mathrm B''}$, such that:
	\begin{enumerate}
		\item $\bigl\| \phi_{\mathrm A} \ot \phi_{\mathrm B} \ket{\psi} - \ket{\mathrm{EPR}_2}^{\ot 2} \ot \ket{\mathrm{aux}} \bigr\| \le O(\sqrt\eps)$;
		\item letting $\tilde A^x_a = \phi_{\mathrm A} A^x_a \phi_{\mathrm A}^\dagger$ and $\tilde B^y_b = \phi_{\mathrm B} B^y_b \phi_{\mathrm B}^\dagger$,
		\begin{align*}
			\tilde A^{\mathsf{Variable}_1}_b \ot I_{\mathrm{B'B''}} &\approx_{\sqrt\eps} (\sigma^X_b)_{\mathrm A'} \ot I_{\mathrm{A''B'B''}}\;,\\
			\tilde A^{\mathsf{Variable}_5}_b \ot I_{\mathrm{B'B''}} &\approx_{\sqrt\eps} (\sigma^Z_b)_{\mathrm A'} \ot I_{\mathrm{A''B'B''}}\;,\\
			I_{\mathrm{A'A''}} \ot \tilde B^{\mathsf{Variable}_1}_b &\approx_{\sqrt\eps} I_{\mathrm{A'A''B''}} \ot (\sigma^X_b)_{\mathrm B'}\;,\\
			I_{\mathrm{A'A''}} \ot \tilde B^{\mathsf{Variable}_5}_b &\approx_{\sqrt\eps} I_{\mathrm{A'A''B''}} \ot (\sigma^Z_b)_{\mathrm B'}\;,
		\end{align*}
		where each $\approx_{\sqrt\eps}$ holds with respect to the state $\ket{\mathrm{EPR}_2}^{\ot 2}_{\mathrm{A'B'}} \ot \ket{\mathrm{aux}}_{\mathrm{A''B''}}$ and the answer summation is over $b \in \{0,1\}$, and the approximation bounds carry implicit universal constants.
	\end{enumerate}
	As a consequence, letting $\tilde A^{\mathsf{Variable}_1} = \tilde A^{\mathsf{Variable}_1}_0 - \tilde A^{\mathsf{Variable}_1}_1$ and $\tilde A^{\mathsf{Variable}_5} = \tilde A^{\mathsf{Variable}_5}_0 - \tilde A^{\mathsf{Variable}_5}_1$ denote the associated observables, it holds that
	\begin{align*}
		\tilde A^{\mathsf{Variable}_1} \tilde A^{\mathsf{Variable}_5} \ot I_{\mathrm{B'B''}} &\approx_{\sqrt\eps} -\, \tilde A^{\mathsf{Variable}_5} \tilde A^{\mathsf{Variable}_1} \ot I_{\mathrm{B'B''}}\;,\\
		I_{\mathrm{A'A''}} \ot \tilde B^{\mathsf{Variable}_1} \tilde B^{\mathsf{Variable}_5} &\approx_{\sqrt\eps} -\, I_{\mathrm{A'A''}} \ot \tilde B^{\mathsf{Variable}_5} \tilde B^{\mathsf{Variable}_1}\;,
	\end{align*}
		where, for operators $M$, $N$ that are not POVM elements, the notation $M \approx_\delta N$ means $\bra{\psi} (M-N)^\dagger (M-N) \ket{\psi} \le O(\delta)$ with respect to the same state.  The symmetry restriction corrects the false arbitrary-strategy statement in the source; see \cite{gap:qpbt_ms-rigidity-symmetric-strategies}.
\end{theorem}
\begin{proof}
		Theorem~6.9 of~\cite{Coladangelo2017Robust} treats the one-way game in
		which one fixed player receives the constraint.  For a symmetric strategy,
		the two orientations in $\mathfrak{G}^{\mathrm{MS}}$ have equal success
		probability, so its value is also the value of either one-way strategy and
		the cited theorem applies.  Without symmetry this reduction is false, as
		shown by the two-copy counterexample in
		\cite{gap:qpbt_ms-rigidity-symmetric-strategies}.  The cited theorem
		measures state closeness in trace norm at scale $O(\eps)$; converting to
		Euclidean distance gives $O(\sqrt\eps)$.  Its ideal observables for
		$\mathsf{Variable}_1$ and $\mathsf{Variable}_5$ are $I \ot \sigma^Z$ and
		$\sigma^Z\sigma^X \ot \sigma^Z\sigma^X$; a local change of basis sends
		them to $\sigma^X \ot I$ and $\sigma^Z \ot I$, respectively.
\end{proof}

\begin{lemma}[One-sided anticommutation in the Magic Square game]
	\label{lem:ms-one-sided-anticommutation}
	\uses{def:ms-game, def:tensor-product-value, def:povm-distance}
	Let $\mathcal S=(\ket\psi,A,B)$ be a projective strategy that succeeds in
	the role-symmetric Magic Square game with probability at least $1-\eps$,
	where $\eps\geq0$.  For $j\in\{1,5\}$, let
	$A^{\mathsf{Variable}_j}=A^{\mathsf{Variable}_j}_0-
	A^{\mathsf{Variable}_j}_1$ and define
	$B^{\mathsf{Variable}_j}$ analogously.  Then, with respect to
	$\ket\psi$,
	\begin{align*}
		A^{\mathsf{Variable}_1}A^{\mathsf{Variable}_5}\ot\Id_{\mathrm B}
		&\approx_{\sqrt\eps}
		- A^{\mathsf{Variable}_5}A^{\mathsf{Variable}_1}\ot\Id_{\mathrm B},\\
		\Id_{\mathrm A}\ot
		B^{\mathsf{Variable}_1}B^{\mathsf{Variable}_5}
		&\approx_{\sqrt\eps}
		-\Id_{\mathrm A}\ot
		B^{\mathsf{Variable}_5}B^{\mathsf{Variable}_1}.
	\end{align*}
\end{lemma}
\begin{proof}
	Split the value of the symmetric game according to which player receives
	the constraint.  The average failure probability of the two orientations is
	at most $\eps$, so each orientation fails with probability at most
	$2\eps$.  Apply the one-way Magic Square self-test of
	\cite[Theorem~6.9]{Coladangelo2017Robust} to each orientation separately.
	In the first orientation it identifies the variable observables of the
	second player with anticommuting Pauli observables; reversing the roles gives
	the same conclusion for the first player.  Pulling these relations back
	through the local isometries and absorbing the factor two into the universal
	constant proves the two displayed estimates.  This consequence does not
	require the full strategy to be symmetric; see
	\cite{gap:qpbt_ms-rigidity-symmetric-strategies}.
\end{proof}

The converse construction shows that any pair of anticommuting binary observables yields a perfect strategy for the Magic Square game.

